WITH with_windows AS (SELECT id, store_id, LAG(quantity) OVER (PARTITION BY product_id ORDER BY last_restock, id) AS prev_quantity, LEAD(quantity) OVER (PARTITION BY product_id ORDER BY last_restock, id) AS next_quantity, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY last_restock, id) AS seq_no FROM inventory) SELECT id, prev_quantity, next_quantity, seq_no FROM with_windows ORDER BY id DESC NULLS FIRST LIMIT 20;
